mapper.update:
update airdrop_info


        `name` = #{name},


        `status` = #{status},


        `task_status` = #{taskStatus},


        `tx_hash` = #{txHash},


        `tx_note` = #{txNote},


        `start_time` = #{startTime},


where info_id = #{infoId}

    and `status` = #{originalStatus}


    and task_status = #{originalTaskStatus}

mapper.select:
select *
from airdrop_info
where `status` = #{status}
  and task_status = #{taskStatus}
  and #{nowDateTime} >= start_time
limit 50

select *
from airdrop_info


        and address = #{address}


        and `status` = #{status}


        and task_status = #{taskStatus}


        and (
        info_id = #{vague}
        or address = #{vague}
        or tx_hash = #{vague}
        or `name` like CONCAT('%', #{vague}, '%')
        )


order by info_id desc
